// ─── Painted terrain features (art override) ────────────────────────────────
//
// Swaps the round feature kinds of TERRAIN_FEATURE_DRAW for painted sprites
// from one small atlas (public/images/terrain/, PAINTED_TERRAIN — generated by
// tools/terrain-sheets/slice-painted.mjs). Per draw, the vector drawing stays
// the fallback:
//  - until the atlas has loaded (the arena's static buffer is re-baked once
//    when it lands: terrainArtRevision() is part of its cache key);
//  - when the sprite would be drawn ABOVE its own resolution (render-sharpness
//    rule: never below css × dpr — the bake's device scale is read from the
//    context transform);
//  - with `?art=procedural` (A/B).
// Islands and mushroom caps keep the procedural flat drop shadow under the
// sprite (the painting has none). Logs stay procedural (variable length).
// Drawn once into the static arena buffer, never per frame.
import { prependBaseUrl } from '@/utils/function'
import { TERRAIN_FEATURE_DRAW } from '@/use/arenaTerrainDraw'
import { PAINTED_TERRAIN, PAINTED_TERRAIN_KINDS } from '@/use/paintedTerrain'

type Ctx = CanvasRenderingContext2D | OffscreenCanvasRenderingContext2D
type Kind = typeof PAINTED_TERRAIN_KINDS[number]
interface Feature { x: number, y: number, radius: number, angle?: number }

const SHADOWED: ReadonlySet<Kind> = new Set<Kind>(['stump', 'rock', 'pond', 'mushroom'])
const DIRECTED: ReadonlySet<Kind> = new Set<Kind>(['booster', 'leafArrow'])

let revision = 0
/** Bumps when painted terrain art becomes available — key the static bake on it. */
export const terrainArtRevision = (): number => revision

let atlas: HTMLImageElement | null = null

const install = () => {
  const meta = PAINTED_TERRAIN
  if (!meta) return
  if (typeof Image === 'undefined' || typeof location === 'undefined') return
  if (typeof navigator !== 'undefined' && /jsdom/i.test(navigator.userAgent)) return
  if (/[?&]art=procedural(?:&|$)/.test(location.search)) return
  const img = new Image()
  img.decoding = 'async'
  img.onload = () => {
    atlas = img
    revision++
  }
  img.src = prependBaseUrl(`images/terrain/${meta.file}?v=${meta.v}`)

  const D = TERRAIN_FEATURE_DRAW as unknown as Record<Kind, (ctx: Ctx, f: Feature) => void>
  const spriteR = meta.cell * meta.rFrac
  PAINTED_TERRAIN_KINDS.forEach((kind, i) => {
    const vector = D[kind]
    if (!vector) return
    D[kind] = (ctx: Ctx, f: Feature) => {
      const t = ctx.getTransform()
      const deviceScale = Math.hypot(t.a, t.b) || 1
      if (!atlas || f.radius * deviceScale > spriteR) {
        vector(ctx, f)
        return
      }
      if (SHADOWED.has(kind)) {
        ctx.fillStyle = 'rgba(0, 0, 0, 0.18)'
        ctx.beginPath()
        ctx.arc(f.x + 3, f.y + 4, f.radius, 0, Math.PI * 2)
        ctx.fill()
      }
      const k = f.radius / spriteR
      const c = meta.cell
      const sx = (i % 3) * c
      const sy = Math.floor(i / 3) * c
      if (DIRECTED.has(kind) && f.angle) {
        ctx.save()
        ctx.translate(f.x, f.y)
        ctx.rotate(f.angle)
        ctx.drawImage(atlas, sx, sy, c, c, -c / 2 * k, -c / 2 * k, c * k, c * k)
        ctx.restore()
      } else {
        ctx.drawImage(atlas, sx, sy, c, c, f.x - c / 2 * k, f.y - c / 2 * k, c * k, c * k)
      }
    }
  })
}

install()
